const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),map=document.querySelector('#map'),mc=map.getContext('2d');
const $=s=>document.querySelector(s),keys=new Set();let width,height,active=false,paused=false,last=0,elapsed=0,toastTime=0,visited=0,camera;
const landmarks=[{name:'Frederick',x:0,z:0},{name:'Middletown',x:-9500,z:1400},{name:'Thurmont',x:-2500,z:23000},{name:'New Market',x:14000,z:-2000},{name:'Brunswick',x:-15000,z:-13000},{name:'Walkersville',x:4500,z:8500}];
const route=[{x:0,z:2100,y:550,name:'Frederick'}, {x:4500,z:8500,y:700,name:'Walkersville'}, {x:-2500,z:17500,y:1000,name:'Catoctin foothills'}, {x:-9500,z:1400,y:900,name:'Middletown valley'}, {x:0,z:-2600,y:500,name:'Frederick Municipal Airport'}];
let plane;function reset(){plane={x:0,z:-4400,y:550,heading:0,pitch:0,bank:0,throttle:.7,speed:49};visited=0;elapsed=0;$('#bar').style.width='0%';updateMission();}
function terrain(x,z){return 70+Math.pow(Math.max(0,Math.sin((x+12000)/3300)),3)*430*Math.exp(-Math.pow((x+13000)/13000,2))+Math.pow(Math.max(0,Math.sin((x+22000)/2100)),4)*160+Math.sin(x/1700)*Math.cos(z/2200)*25;}
function river(z){return 5200+Math.sin(z/4500)*1600+Math.sin(z/1500)*350;}
function resize(){width=innerWidth;height=innerHeight;canvas.width=width*devicePixelRatio;canvas.height=height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);}addEventListener('resize',resize);resize();reset();
function project(x,y,z){let dx=x-camera.x,dz=z-camera.z,dy=y-camera.y;let side=dx*Math.cos(plane.heading)-dz*Math.sin(plane.heading),depth=dx*Math.sin(plane.heading)+dz*Math.cos(plane.heading);let tilt=-.14+plane.pitch*.45;let yy=dy*Math.cos(tilt)-depth*Math.sin(tilt),zz=dy*Math.sin(tilt)+depth*Math.cos(tilt);if(zz<40)return null;let f=height*.92;let sx=side*f/zz,sy=-yy*f/zz;let b=-plane.bank*.2;return{x:width/2+sx*Math.cos(b)-sy*Math.sin(b),y:height*.43+sx*Math.sin(b)+sy*Math.cos(b),d:zz};}
function poly(points,color,stroke){let p=points.map(a=>project(...a));if(p.some(v=>!v))return;ctx.beginPath();p.forEach((v,i)=>i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y));ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
const colors=['#8d9e61','#b9b776','#78965b','#a5ab69','#728b54','#c3b781','#929d63'];
function ground(){let cells=[],size=800,cx=Math.floor(plane.x/size),cz=Math.floor(plane.z/size);for(let i=-23;i<=23;i++)for(let j=-23;j<=23;j++){let x=(cx+i)*size,z=(cz+j)*size;let depth=(x-camera.x)*Math.sin(plane.heading)+(z-camera.z)*Math.cos(plane.heading);if(depth<150||depth>22000)continue;cells.push({x,z,d:depth});}cells.sort((a,b)=>b.d-a.d);for(let t of cells){let {x,z,d}=t;let n=Math.abs(Math.sin(x*.00041+z*.00083)*10000)|0;let color=colors[n%colors.length];if(terrain(x,z)>230)color=['#466b50','#577651','#658058'][n%3];poly([[x,terrain(x,z),z],[x+size,terrain(x+size,z),z],[x+size,terrain(x+size,z+size),z+size],[x,terrain(x,z+size),z+size]],color);if(d<14000&&Math.abs(x-river(z))<900)poly([[river(z)-65,terrain(river(z),z)+3,z],[river(z)+65,terrain(river(z),z)+3,z],[river(z+size)+65,terrain(river(z+size),z+size)+3,z+size],[river(z+size)-65,terrain(river(z+size),z+size)+3,z+size]],'#689fa5');if(n%7===0&&d<9000){let tx=x+320,tz=z+360,ty=terrain(tx,tz);poly([[tx-65,ty,tz],[tx+65,ty,tz],[tx+65,ty,tz+120],[tx-65,ty,tz+120]],'#ede0b2');poly([[tx-65,ty+75,tz],[tx+65,ty+75,tz],[tx+65,ty+75,tz+120],[tx-65,ty+75,tz+120]],'#785344');}}
// Regional roads and airport are landmarks in an intentionally stylized landscape.
for(let z=-17000;z<26000;z+=500){let x=800+z*.1;poly([[x-22,terrain(x,z)+5,z],[x+22,terrain(x,z)+5,z],[x+72,terrain(x+50,z+500)+5,z+500],[x+28,terrain(x+50,z+500)+5,z+500]],'#c9c1a0');}
poly([[-70,90,-4200],[70,90,-4200],[70,90,-2300],[-70,90,-2300]],'#45555a');for(let z=-4100;z<-2400;z+=180)poly([[-5,91,z],[5,91,z],[5,91,z+65],[-5,91,z+65]],'#eee8cb');
for(let town of landmarks){for(let i=0;i<36;i++){let x=town.x+(i%6-3)*150,z=town.z+(Math.floor(i/6)-3)*150,y=terrain(x,z);poly([[x-35,y+50,z-40],[x+35,y+50,z-40],[x+35,y+50,z+40],[x-35,y+50,z+40]],i%3?'#dfd4b7':'#aa795d');}let p=project(town.x,terrain(town.x,town.z)+200,town.z);if(p&&p.d<18000&&p.x>0&&p.x<width){ctx.font='11px system-ui';let w=ctx.measureText(town.name).width;ctx.fillStyle='#17383caa';ctx.fillRect(p.x-w/2-9,p.y-15,w+18,25);ctx.fillStyle='#fff4d8';ctx.textAlign='center';ctx.fillText(town.name,p.x,p.y+2);}}
}
function rings(){if(visited>=route.length)return;let r=route[visited];let points=[];for(let a=0;a<=Math.PI*2+.01;a+=Math.PI/40)points.push(project(r.x+Math.cos(a)*180,r.y+Math.sin(a)*180,r.z));if(points.every(Boolean)){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#f4cc73';ctx.lineWidth=Math.max(3,16000/points[0].d);ctx.shadowColor='#ffde89';ctx.shadowBlur=15;ctx.stroke();ctx.shadowBlur=0;let p=project(r.x,r.y+240,r.z);if(p){ctx.fillStyle='#fff4ce';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText(r.name+' · '+Math.round(Math.hypot(r.x-plane.x,r.z-plane.z)/100)/10+' km',p.x,p.y);}}
let relative=Math.atan2(r.x-plane.x,r.z-plane.z)-plane.heading;relative=Math.atan2(Math.sin(relative),Math.cos(relative));ctx.save();ctx.translate(width/2,105);ctx.fillStyle='#edcb82';ctx.font='12px system-ui';ctx.textAlign='center';ctx.fillText(relative<-.25?'← Next ring':relative>.25?'Next ring →':'Next ring ↑',0,0);ctx.restore();}
function aircraft(){ctx.save();ctx.translate(width*.5,height*.68);ctx.rotate(-plane.bank*.8);let s=Math.min(width/1100,1.2);ctx.scale(s,s);ctx.shadowColor='#163e4655';ctx.shadowBlur=18;ctx.fillStyle='#f1ead6';ctx.beginPath();ctx.moveTo(-175,2);ctx.lineTo(-26,-12);ctx.lineTo(-13,-38);ctx.lineTo(13,-38);ctx.lineTo(26,-12);ctx.lineTo(175,2);ctx.lineTo(175,13);ctx.lineTo(22,12);ctx.lineTo(12,53);ctx.lineTo(53,64);ctx.lineTo(53,73);ctx.lineTo(-53,73);ctx.lineTo(-53,64);ctx.lineTo(-12,53);ctx.lineTo(-22,12);ctx.lineTo(-175,13);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#c85537';ctx.fillRect(-165,2,24,10);ctx.fillRect(141,2,24,10);ctx.fillStyle='#315967';ctx.beginPath();ctx.ellipse(0,-10,11,20,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b6baa7';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,15);ctx.lineTo(0,64);ctx.stroke();ctx.strokeStyle='#ffffff55';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,-40,30,4,elapsed*40,0,Math.PI*2);ctx.stroke();ctx.restore();}
function minimap(){mc.fillStyle='#244846';mc.fillRect(0,0,210,180);const mp=(x,z)=>[105+x/240,120-z/260];mc.strokeStyle='#81aaa0';mc.lineWidth=3;mc.beginPath();for(let z=-16000;z<28000;z+=300){let p=mp(river(z),z);z===-16000?mc.moveTo(...p):mc.lineTo(...p);}mc.stroke();mc.strokeStyle='#567657';mc.lineWidth=14;mc.beginPath();mc.moveTo(...mp(-12500,-15000));mc.lineTo(...mp(-8000,26000));mc.stroke();mc.font='8px system-ui';mc.textAlign='center';for(let t of landmarks){let p=mp(t.x,t.z);mc.fillStyle='#bdd1b6';mc.fillRect(p[0]-2,p[1]-2,4,4);mc.fillText(t.name,p[0],p[1]-6);}mc.strokeStyle='#e7bc6c88';mc.lineWidth=1;mc.beginPath();route.forEach((r,i)=>{let p=mp(r.x,r.z);i?mc.lineTo(...p):mc.moveTo(...p);});mc.stroke();if(visited<5){let p=mp(route[visited].x,route[visited].z);mc.strokeStyle='#edc77b';mc.beginPath();mc.arc(...p,5,0,Math.PI*2);mc.stroke();}let p=mp(plane.x,plane.z);mc.save();mc.translate(...p);mc.rotate(plane.heading);mc.fillStyle='#fff6d9';mc.beginPath();mc.moveTo(0,-7);mc.lineTo(5,5);mc.lineTo(0,2);mc.lineTo(-5,5);mc.closePath();mc.fill();mc.restore();}
function updateMission(){$('#target').textContent=visited<5?route[visited].name:'Scenic route complete';$('#progress').textContent=visited<5?'Fly through the golden rings · '+visited+' / 5':'All 5 rings collected · keep exploring';$('#bar').style.width=visited*20+'%';}
function toast(t){$('#message').textContent=t;$('#message').style.display='block';toastTime=4;}
function update(dt){elapsed+=dt;if(keys.has('w'))plane.throttle=Math.min(1,plane.throttle+dt*.2);if(keys.has('s'))plane.throttle=Math.max(.2,plane.throttle-dt*.2);let turn=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0);let pitch=(keys.has('ArrowUp')?1:0)-(keys.has('ArrowDown')?1:0);plane.bank+=(turn*.55-plane.bank)*Math.min(1,dt*3);plane.pitch+=(pitch*.27-plane.pitch)*Math.min(1,dt*2);if(keys.has(' ')){plane.bank*=Math.exp(-dt*8);plane.pitch*=Math.exp(-dt*8);}plane.heading+=plane.bank*dt*.5;plane.speed+=(25+plane.throttle*40-plane.speed)*dt*.6;plane.x+=Math.sin(plane.heading)*plane.speed*dt*3;plane.z+=Math.cos(plane.heading)*plane.speed*dt*3;plane.y+=Math.sin(plane.pitch)*plane.speed*dt*3;let floor=terrain(plane.x,plane.z)+55;if(plane.y<floor){plane.y=floor;plane.pitch=Math.max(.08,plane.pitch);toast('Terrain assist · lifting you clear of the ground');}plane.y=Math.min(2300,plane.y);if(Math.abs(plane.x)>22000||plane.z>30000||plane.z<-19000){plane.heading=Math.atan2(-plane.x,6000-plane.z);toast('Heading back into Frederick County');}if(visited<5){let r=route[visited];if(Math.hypot(plane.x-r.x,plane.z-r.z)<220&&Math.abs(plane.y-r.y)<185){visited++;updateMission();toast(visited===5?'Route complete! Enjoy the open sky.':'Ring collected · '+visited+' of 5');}}if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#message').style.display='none';}}
function frame(t){let dt=Math.min((t-last)/1000,.05);last=t;if(active&&!paused)update(dt);camera={x:plane.x-Math.sin(plane.heading)*290,y:plane.y+105,z:plane.z-Math.cos(plane.heading)*290};let sky=ctx.createLinearGradient(0,0,0,height*.65);sky.addColorStop(0,'#5e9cae');sky.addColorStop(.65,'#bdd3c7');sky.addColorStop(1,'#e7dbb6');ctx.fillStyle=sky;ctx.fillRect(0,0,width,height);ctx.fillStyle='#a1af7d';ctx.fillRect(0,height*.55,width,height*.45);ground();rings();aircraft();minimap();$('#speed').textContent=Math.round(plane.speed*1.944);$('#altitude').textContent=Math.round((plane.y-terrain(plane.x,plane.z))*3.281).toLocaleString();$('#heading').textContent=String(Math.round((plane.heading*180/Math.PI%360+360)%360)).padStart(3,'0');$('#throttle').textContent=Math.round(plane.throttle*100);let town=landmarks.reduce((a,b)=>Math.hypot(a.x-plane.x,a.z-plane.z)<Math.hypot(b.x-plane.x,b.z-plane.z)?a:b);$('#near').textContent='Above '+town.name+(town.name==='Frederick'?' & the Monocacy valley':'');requestAnimationFrame(frame);}requestAnimationFrame(frame);
function togglePause(){if(!active)return;paused=!paused;keys.clear();$('#pause').textContent=paused?'Resume':'Pause';if(paused)toast('Flight paused · press P to resume');else $('#message').style.display='none';}
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();let k=e.key.length===1?e.key.toLowerCase():e.key;if(!e.repeat){if(k==='p')togglePause();if(k==='r'){reset();toast('Fresh flight · welcome back to Frederick');}if(k==='Escape'&&active){$('#overlay').style.display='none';if(paused)togglePause();}}keys.add(k);});addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));addEventListener('blur',()=>{keys.clear();if(active&&!paused)togglePause();});$('#start').onclick=()=>{active=true;paused=false;$('#pause').textContent='Pause';$('#overlay').style.display='none';keys.clear();toast('Welcome aboard · ↑ to climb, ← → to turn');};$('#pause').onclick=togglePause;$('#help').onclick=()=>{if(active&&!paused)togglePause();$('#start').innerHTML='Return to flight <span>↗</span>';$('#overlay').style.display='flex';};
// Read-only flight telemetry for diagnostics.
window.flightState=()=>({...plane,visited,active,paused});
